const enfermedadData=[{"disease":"Le gustó a todos y no lo usó nadie","characteristic":"La promesa era tan general que nadie se reconoció en ella","opts":["La promesa era tan general que nadie se reconoció en ella","Faltó presupuesto de publicidad","El logo no era bonito","No estaba en redes sociales"]},{"disease":"Se gastó todo en el logo y la maestra sigue preguntando para qué sirve","characteristic":"Se empezó por la etiqueta antes de tener promesa","opts":["Se empezó por la etiqueta antes de tener promesa","El diseñador cobró de más","Los colores estaban mal elegidos","Faltaba una tarjeta de presentación"]},{"disease":"Preguntaron «¿cuántos maestros exactamente?» y no hubo respuesta","characteristic":"Se publicó un número que nadie podía verificar","opts":["Se publicó un número que nadie podía verificar","La pregunta fue malintencionada","Faltó un estudio de mercado","El dato estaba desactualizado"]},{"disease":"La madre lo abrió una vez y no volvió","characteristic":"La promesa exigía datos que ella no tiene","opts":["La promesa exigía datos que ella no tiene","El contenido era muy difícil","No le interesaba la educación","Faltaban más colores"]},{"disease":"El material circula por todo el país y nadie sabe quién lo hizo","characteristic":"Se entregó sin exigir el nombre del autor en la portada","opts":["Se entregó sin exigir el nombre del autor en la portada","La distribución fue demasiado rápida","El material era muy bueno","Faltó registrar la marca"]},{"disease":"Terminó el acuerdo con la página grande y no quedó nadie","characteristic":"El público era prestado y se devolvió completo","opts":["El público era prestado y se devolvió completo","La página incumplió el trato","El contenido dejó de gustar","Cambió el algoritmo"]}];
let enferIdx=0,enferDone=false;
function showEnfer(){enferDone=false;if(enferIdx>=enfermedadData.length){const el=document.getElementById('enferDisease');if(el)el.textContent='🎉 ¡Completado!';const opts=document.getElementById('enferOpts');if(opts)opts.innerHTML='';return;}const d=enfermedadData[enferIdx];const prog=document.getElementById('enferProg');if(prog)prog.textContent=`${enferIdx+1} de ${enfermedadData.length}`;const dis=document.getElementById('enferDisease');if(dis)dis.textContent=d.disease;const opts=document.getElementById('enferOpts');if(!opts)return;opts.innerHTML='';_shuffle([...d.opts]).forEach(opt=>{const b=document.createElement('button');b.className='qz-opt';b.textContent=opt;b.onclick=()=>checkEnfer(opt,b,d);opts.appendChild(b);});const fbEl=document.getElementById('fbEnfer');if(fbEl)fbEl.classList.remove('show');}
function checkEnfer(opt,btn,d){if(enferDone)return;enferDone=true;document.querySelectorAll('#enferOpts .qz-opt').forEach(b=>{if(b.textContent===d.characteristic)b.classList.add('correct');else if(b===btn&&b.textContent!==d.characteristic)b.classList.add('wrong');});const isOk=opt===d.characteristic;if(isOk){fb('fbEnfer','¡Correcto! +3 XP',true);if(!xpTracker.wgt.has('enfer_'+enferIdx)){xpTracker.wgt.add('enfer_'+enferIdx);pts(3);}sfx('ok');}else{fb('fbEnfer','Correcto: '+d.characteristic,false);sfx('no');}setTimeout(()=>{enferIdx++;showEnfer();},1800);}
function resetEnfer(){sfx('click');enferIdx=0;showEnfer();}

