const identifyTaskDB=[{"s":"La promesa que alguien recuerda cuando uno no está.","type":"Marca"},{"s":"Lo que el trabajo es o tiene, sin hablar de la persona.","type":"Característica"},{"s":"Lo que le cambia a quien lo usa.","type":"Beneficio"},{"s":"Algo que se puede tocar y comprobar hoy.","type":"Prueba"},{"s":"La persona concreta para quien es esto.","type":"Audiencia"},{"s":"La etiqueta que se pone al final, cuando ya hay promesa.","type":"Logo"},{"s":"La franja estrecha donde uno es la mejor opción.","type":"Nicho"},{"s":"Para qué te contrata de verdad esa persona.","type":"Trabajo por hacer"},{"s":"Lo que una maestra le dice a otra sin que uno esté delante.","type":"Boca a boca"},{"s":"La cifra grande que nadie puede verificar.","type":"Número inflado"}];
const classifyTaskDB=[{"w":"Tiene 57 misiones","gen":"Mensaje","n":"Producto","g":"Característica","t":"Habla del producto"},{"w":"No trasnocha preparando la clase","gen":"Mensaje","n":"Persona","g":"Beneficio","t":"Habla de la persona"},{"w":"Funciona sin internet","gen":"Mensaje","n":"Producto","g":"Característica","t":"Habla del producto"},{"w":"El niño estudia aunque se vaya la luz","gen":"Mensaje","n":"Persona","g":"Beneficio","t":"Habla de la persona"},{"w":"Maestra de sexto que enseña fracciones","gen":"Audiencia","n":"Concreta","g":"Concreta","t":"Se puede describir"},{"w":"La comunidad educativa en general","gen":"Audiencia","n":"Vaga","g":"Todo el mundo","t":"No se reconoce nadie"},{"w":"43 fichas publicadas desde febrero","gen":"Afirmación","n":"Verificable","g":"Con prueba","t":"Se puede comprobar"},{"w":"Usado por miles de maestros","gen":"Afirmación","n":"Vaga","g":"Sin prueba","t":"Nadie puede comprobarlo"},{"w":"Mañana tienes la clase lista","gen":"Frase","n":"Promesa","g":"Promesa","t":"Dice qué cambia"},{"w":"Un logo moderno y limpio","gen":"Frase","n":"Adorno","g":"Adorno","t":"No dice qué cambia"}];
const completeTaskDB=[{"s":"La marca es la ___ que alguien recuerda cuando uno no está.","opts":["promesa","imagen","oferta"],"ans":"promesa"},{"s":"Lo que el producto es o tiene se llama ___.","opts":["característica","beneficio","adorno"],"ans":"característica"},{"s":"Lo que le cambia a quien lo usa se llama ___.","opts":["beneficio","característica","prueba"],"ans":"beneficio"},{"s":"Una promesa sin prueba es solo ___.","opts":["publicidad","estrategia","diferencia"],"ans":"publicidad"},{"s":"Toda característica se traduce agregándole «___ que».","opts":["para","porque","aunque"],"ans":"para"},{"s":"Una audiencia que sirve para todos no le sirve a ___.","opts":["nadie","todos","algunos"],"ans":"nadie"},{"s":"El nombre y el logo se deciden al ___.","opts":["final","principio","comienzo"],"ans":"final"},{"s":"La franja estrecha donde uno es la mejor opción es el ___.","opts":["nicho","canal","sello"],"ans":"nicho"}];
const explainQuestions=[{"q":"Explica con tus palabras la diferencia entre característica y beneficio, con un ejemplo de M.E.T.A.S.","ans":"La característica es lo que el trabajo es o tiene: «la ficha tiene diez páginas», «funciona sin internet». Es verdad y es verificable, pero le habla al producto. El beneficio es lo que eso le cambia a la persona que lo usa: «la maestra llega al aula sin preparar nada», «el niño sigue estudiando aunque se vaya la luz». Se traduce agregando «para que» hasta que aparezca una persona: si después del «para que» solo aparece el producto, todavía es característica."},{"q":"¿Por qué «para todo el mundo» no es una audiencia? Da un ejemplo del propio proyecto.","ans":"Porque un mensaje que sirve igual a una maestra de sexto, a un ingeniero y a un abuelo no hace que ninguno se reconozca en él, y lo que no se reconoce no se repite a un tercero. Cuando una escuela pide material «para todos los grados y todas las materias», el trabajo se reparte tan fino que ninguna materia queda buena y el mensaje se vuelve tan general que nadie lo recomienda. La audiencia amplia se gana estrechando: ser conocido por «las mejores fichas de sexto» abre más puertas que ser conocido por «material educativo variado»."},{"q":"Escribe la promesa de M.E.T.A.S en doce palabras y las tres pruebas que la sostienen.","ans":"Promesa: «Misiones y fichas listas para imprimir: la maestra tiene mañana la clase preparada». Las tres pruebas, todas comprobables hoy: (1) las fichas impresas de diez páginas con su pauta, que llegan al aula sin preparar nada; (2) el Campeonísimo con preguntas de siete materias funcionando, no prometido para después; (3) las misiones abriendo en un teléfono con datos escasos y siguiendo sin conexión. La prueba es lo que separa una promesa de la publicidad."},{"q":"Llega un patrocinador que ofrece 8.000 lempiras por su logo en la portada de las fichas. ¿Qué se cede, qué no y con qué condición se acepta?","ans":"Se cede espacio de marca, que es real y tiene precio. No se cede la portada, porque es donde la maestra decide en dos segundos si esto es material educativo o publicidad, ni la autoría ni el criterio pedagógico. La condición: logo en la contraportada, con tamaño y lugar definidos por escrito, y reglas de patrocinio publicadas iguales para todos, de modo que el no al siguiente no sea personal sino la regla."},{"q":"¿Por qué el nombre y el logo van al final y no al principio?","ans":"Porque el logo es la etiqueta que se le pone a una promesa, y una etiqueta sobre un frasco vacío no dice nada. Si primero no está claro para quién es y qué le cambia, ningún logo hace que la maestra entienda para qué le sirve. Además, decisiones de imagen tomadas antes de conocer a la audiencia suelen apuntar al lugar equivocado: un nombre en inglés en un centro rural aleja en vez de acercar. Primero audiencia, después promesa, después prueba, y al final el nombre."},{"q":"¿Qué es el público prestado y por qué conviene vigilarlo?","ans":"Es la audiencia que vive en la casa de otro: una página grande que difunde el material a cambio de exclusividad. Mete alcance inmediato, pero al terminar el acuerdo el público sigue siendo de la página y hay que empezar de nuevo. La forma sana de colaborar es sin exclusividad, con el nombre visible y un enlace al sitio propio, de modo que cada publicación deje algo que se queda. La regla: público prestado se devuelve completo."}];
let ansVisible=false;
function genTask(){sfx('click');const type=document.getElementById('tgType').value;const count=parseInt(document.getElementById('tgCount').value);ansVisible=false;const out=document.getElementById('tgOut');out.innerHTML='';if(type==='identify')genIdentifyTask(out,count);else if(type==='classify')genClassifyTask(out,count);else if(type==='complete')genCompleteTask(out,count);else if(type==='explain')genExplainTask(out,count);fin('s-tareas');}
function _instrBlock(out,title,lines){const ib=document.createElement('div');ib.className='tg-instruction-block';ib.innerHTML=`<h4>📋 ${title}</h4>`+lines.map(l=>`<p>${l}</p>`).join('');out.appendChild(ib);}
function genIdentifyTask(out,count){_instrBlock(out,'Instrucción',['Copia en tu cuaderno; subraya, colorea o encierra el concepto técnico ilustrado en cada oración. Escribe al lado de qué concepto se trata.','<strong>Ejemplo:</strong> Un solo contraejemplo basta para refutar una ley. → <span style="color:var(--jade);font-weight:700;">Falsacionismo</span>']);_pick(identifyTaskDB,Math.min(count,identifyTaskDB.length)).forEach((item,i)=>{const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.s}</strong><div style="border-bottom:1.5px solid var(--border);min-width:220px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.type}</div></div>`;out.appendChild(div);});}
function genClassifyTask(out,count){_instrBlock(out,'Instrucción',['Copia la siguiente tabla en tu cuaderno. Para cada elemento, completa su tipo, características, ámbito y función.']);const items=_pick(classifyTaskDB,Math.min(count,classifyTaskDB.length));const wrap=document.createElement('div');wrap.style.overflowX='auto';const th=(t,extra='')=>`<th style="padding:0.3rem 0.4rem;border:1px solid var(--border);font-size:0.72rem;text-align:center;${extra}">${t}</th>`;let html=`<table style="width:100%;border-collapse:collapse;font-size:0.78rem;min-width:520px;"><thead><tr style="background:var(--pri-gl);">${th('Elemento','text-align:left;')}${th('Tipo')}${th('Características')}${th('Ámbito')}${th('Función')}</tr></thead><tbody>`;items.forEach(it=>{html+=`<tr><td style="padding:0.4rem 0.5rem;border:1px solid var(--border);font-weight:600;">${it.w}</td>`+Array(4).fill(`<td style="padding:0.4rem;border:1px solid var(--border);min-width:50px;"></td>`).join('')+'</tr>';});html+='</tbody></table>';wrap.innerHTML=html;out.appendChild(wrap);const ans=document.createElement('div');ans.className='tg-answer';ans.style.marginTop='0.8rem';ans.innerHTML='<strong>✅ Respuestas:</strong><br>'+items.map(it=>`<strong>${it.w}:</strong> Tipo: ${it.gen} | Características: ${it.n} | Ámbito: ${it.g} | Función: ${it.t}`).join('<br>');out.appendChild(ans);}
function genCompleteTask(out,count){_instrBlock(out,'Instrucción',['Copia y resuelve en tu cuaderno. Cada oración tiene un espacio ___. Elige y escribe la opción correcta.']);const pool=_shuffle([...completeTaskDB]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';const sent=item.s.replace('___','<span class="tg-blank" style="min-width:90px;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span>');div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${sent}</strong><div style="margin-top:0.4rem;font-size:0.82rem;color:var(--gray);">📝 Opciones: <strong>${item.opts.join(' | ')}</strong></div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function genExplainTask(out,count){_instrBlock(out,'Instrucción',['Copia las siguientes preguntas en tu cuaderno y responde cada una de forma clara y argumentada.']);const pool=_shuffle([...explainQuestions]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.q}</strong><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.3rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function toggleAns(){ansVisible=!ansVisible;document.querySelectorAll('.tg-answer').forEach(el=>el.style.display=ansVisible?'block':'none');sfx('click');}

