function evalSwitchMode(mode){
  sfx('click');
  const cWrap=document.getElementById('evalConceptWrap'),critWrap=document.getElementById('evalCritWrap');
  const cBtn=document.getElementById('evalModeBtnConcept'),critBtn=document.getElementById('evalModeBtnCrit');
  if(mode==='crit'){
    cWrap.style.display='none';critWrap.style.display='block';
    cBtn.classList.remove('active');cBtn.setAttribute('aria-selected','false');
    critBtn.classList.add('active');critBtn.setAttribute('aria-selected','true');
    if(!window._evalCritData)genEvalCrit();
  }else{
    critWrap.style.display='none';cWrap.style.display='block';
    critBtn.classList.remove('active');critBtn.setAttribute('aria-selected','false');
    cBtn.classList.add('active');cBtn.setAttribute('aria-selected','true');
  }
}

const critCaseBank=[{"txt":"Son las nueve de la noche. Una maestra de sexto busca en el teléfono material de fracciones para mañana, con el niño ya dormido y sin haber preparado nada."},{"txt":"Una madre con un solo teléfono para la casa y datos contados quiere que su hija siga estudiando en las tardes. La luz se va tres veces por semana."},{"txt":"Un negocio del barrio ofrece 8.000 lempiras a cambio de que su logo aparezca en la portada de todas las fichas del año."},{"txt":"Alguien con buena intención aconseja cambiarle el nombre al proyecto por uno en inglés, con colores nuevos y una tipografía más profesional."},{"txt":"Una escuela pide que el material cubra de primero a noveno, todas las asignaturas, y que además sirva a los padres en casa."},{"txt":"Proponen poner «usado por miles de maestros» en la portada del sitio, sin tener el dato, porque «así se ve más serio»."},{"txt":"Una editorial ofrece distribuir las fichas en su catálogo con su sello en la portada y el nombre del autor en la página de créditos."},{"txt":"Una página con mucho público ofrece publicar las misiones a cambio de que no se publiquen en ningún otro lado durante un año."}];
const critCaseQuestions=["1. ¿A quién le habla de verdad esta situación, y qué quiere esa persona?","2. ¿Qué se está prometiendo, y con qué prueba se comprueba hoy?","3. Escribe en 3-4 frases qué se cede aquí sin darse cuenta.","4. Reescribe la promesa o la respuesta en doce palabras."];
const critCaseGuides=["La audiencia no es «la comunidad educativa»: es una persona con su hora y su apuro. Nombrarla con su situación cambia todo el mensaje, porque lo que estorba a esa hora rompe la promesa aunque el contenido sea excelente.","La promesa se dice en una frase corta y verificable, y detrás va la prueba que se toca hoy: una ficha impresa, una misión abierta, una maestra que lo diga con su nombre. Sin prueba, es publicidad.","Lo que se cede casi nunca es dinero: es autoría, espacio de marca, lectura de qué es esto, relación directa con el público o libertad para seguir publicando. Eso es lo que hay que poner en la balanza.","Doce palabras obligan a decidir para quién es. Si no cabe, es que todavía hay dos audiencias metidas en la misma frase."];

const critErrorBank=[{"txt":"\"Lo que le falta al proyecto es un logo moderno y un nombre en inglés\".","g1":"El logo es la etiqueta de una promesa; sin promesa clara no hay nada que etiquetar, y la maestra sigue sin saber para qué le sirve.","g2":"El orden correcto es audiencia, promesa, prueba y al final el nombre. Un nombre en inglés en un centro rural aleja en vez de acercar."},{"txt":"\"Pongamos que lo usan miles de maestros, total nadie va a preguntar\".","g1":"Basta una persona que pregunte «¿cuántos exactamente?» para derribar la cifra y, con ella, lo que sí era cierto.","g2":"Un número chico con fecha convence más porque el que lo lee sabe que puede comprobarlo. 43 fichas desde febrero vale más que «miles»."},{"txt":"\"Mientras más amplio el mensaje, más gente lo va a usar\".","g1":"Un mensaje para todos no hace que nadie se reconozca en él, y lo que no se reconoce no se repite a un tercero.","g2":"La audiencia amplia se gana estrechando: hacerlo impecable para un grado y una materia, y crecer desde ahí con una maestra que lo diga con su nombre."},{"txt":"\"Aceptemos el logo del patrocinador en la portada, total es solo un espacio\".","g1":"La portada es donde la maestra decide en dos segundos si esto es material educativo o publicidad. No se cede espacio: se cede la lectura de qué es esto.","g2":"Contraportada, tamaño definido por escrito y reglas publicadas iguales para todos. Así el no al siguiente no es personal, es la regla."},{"txt":"\"Que la editorial ponga su sello, lo importante es que el material llegue lejos\".","g1":"El material llega y la reputación se queda en otra parte: quien lo recuerde recordará a la editorial, no al autor.","g2":"Se puede volver a hacer una ficha; no se puede volver a ser el primero que la hizo. Nombre en portada y licencia para seguir publicando lo propio."},{"txt":"\"Con la exclusividad de un año ganamos público de golpe\".","g1":"El público es de la página, no del proyecto: al terminar el acuerdo se devuelve completo y hay que empezar de nuevo.","g2":"Difusión sin exclusividad, con enlace al sitio propio y nombre visible, para que cada publicación deje algo que se queda."}];

const critDecisionBank=["La maestra de sexto busca material a las nueve de la noche: ¿qué parte de la promesa hay que proteger para no perderla?","La madre solo tiene el teléfono y datos contados: ¿qué característica se convierte aquí en el beneficio principal?","Un negocio ofrece 8.000 lempiras por su logo en la portada: ¿qué se cede, qué no y con qué condición se acepta?","Aconsejan cambiar el nombre y el logo antes que nada: ¿en qué orden se hacen de verdad las cosas y por qué?","Una escuela pide material para todos los grados y materias: ¿qué se contraoferta y con qué argumento?","Proponen publicar «usado por miles de maestros» sin el dato: ¿qué se publica en su lugar?","Una editorial quiere el material con su sello: ¿qué se pide antes de entregar nada?","Una página grande ofrece difusión con exclusividad de un año: ¿cómo se acepta sin quedarse sin público propio?"];
const critDecisionGuide="La decisión correcta sigue los principios de la casa: se identifica quién firma, quién traba y quién paga antes de responder; se empieza pequeño y reversible; nunca se compromete a terceros que no firmaron; la autoría y el uso se acuerdan antes de entregar, no después; y todo queda por escrito con la institución y no con la persona. Cuando la oferta es grande y urgente, esa combinación es justamente la señal para tomarse los días que hagan falta y responder con una condición concreta.";

const critCompareBank=[{"a":"La ficha se abre e imprime en tres clics, sin cuenta.","b":"La ficha se descarga tras registrarse y esperar un correo de confirmación.","ga":"Caso A: cumple la promesa a la hora en que la maestra decide, que es de noche y con apuro.","gb":"Caso B: pierde a la clienta sin que uno se entere, porque a esa hora nadie espera un correo."},{"a":"«43 fichas publicadas desde febrero, usadas en tres centros».","b":"«Material educativo usado por miles de maestros en todo el país».","ga":"Caso A: número chico, con fecha y verificable. El que lo lee sabe que puede comprobarlo.","gb":"Caso B: una sola pregunta lo derriba y se lleva también lo que sí era cierto."},{"a":"Hacerlo impecable para sexto grado y crecer desde ahí.","b":"Cubrir de primero a noveno y todas las materias de una vez.","ga":"Caso A: alguien puede decir «las mejores fichas de sexto», y eso se repite entre colegas.","gb":"Caso B: el trabajo se reparte tan fino que ninguna materia queda buena y nadie lo recomienda."},{"a":"Logo del patrocinador en la contraportada, con tamaño por escrito.","b":"Logo del patrocinador en la portada, junto al nombre del proyecto.","ga":"Caso A: se cede espacio real sin cambiar cómo se lee el material.","gb":"Caso B: la maestra decide en dos segundos que esto es publicidad, y ya no la convence el contenido."}];

const critCauseBank=[{"cause":"Se elige «la comunidad educativa» como audiencia.","guide":"El mensaje se vuelve tan general que nadie se reconoce en él, y sin reconocimiento no hay boca a boca. Hay que bajar a una persona con hora y problema."},{"cause":"Se publica una cifra grande sin fuente ni fecha.","guide":"La primera pregunta la derriba y arrastra la credibilidad de lo que sí era cierto. La confianza no se pierde por parecer pequeño, sino por parecer inflado."},{"cause":"Se gasta el presupuesto en identidad visual antes de tener promesa.","guide":"Queda una etiqueta preciosa sobre un frasco vacío: nadie sabe repetir qué hace el proyecto, que es justo lo que hace crecer."},{"cause":"Se acepta que el material circule con el sello de otro.","guide":"El alcance sube y la marca se queda en otra parte. Se puede rehacer una ficha; no se puede volver a ser el primero que la hizo."},{"cause":"Se firma exclusividad con una página de mucho público.","guide":"Al terminar el año el público sigue siendo de la página. Público prestado se devuelve completo."},{"cause":"La misión pesa demasiado para un teléfono con datos contados.","guide":"La promesa era falsa para esa audiencia desde el principio, y una promesa que falla la primera vez no tiene segunda."}];
const critEffectBank=[{"effect":"Una maestra le pasó la ficha a otras tres sin que nadie se lo pidiera.","guide":"La promesa se entendió, se pudo comprobar y por eso se repitió. Eso es la marca funcionando, y no costó nada."},{"effect":"El proyecto quedó conocido como «las fichas de sexto» en todo el distrito.","guide":"Estrechar funcionó: un nicho claro se recuerda y se recomienda, y desde ahí se puede crecer hacia otros grados."},{"effect":"Un patrocinador aceptó la contraportada sin discutir.","guide":"Las reglas publicadas hicieron el trabajo: el límite no fue personal, fue la norma, y eso deja la puerta abierta para el año siguiente."},{"effect":"Preguntaron por los números y la respuesta estuvo lista, con fecha.","guide":"Publicar cifras reales y verificables convierte una pregunta incómoda en una demostración de seriedad."},{"effect":"La madre siguió usando las misiones el mes en que se fue la luz cuatro veces.","guide":"La característica técnica era exactamente el beneficio de esa audiencia, y por eso se dice primero."},{"effect":"La editorial aceptó el nombre del autor en la portada.","guide":"Se pidió antes de entregar nada. Lo que se pide antes se negocia; lo que se reclama después ya se perdió."}];

function genEvalCrit(){
  sfx('click');
  _injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});const _sC=document.getElementById('evalCritFormaSel');if(_sC&&parseInt(_sC.value,10))evalCritFormNum=Math.min(EVAL_FORMAS,Math.max(1,parseInt(_sC.value,10)));const cf=evalCritFormNum;window._currentEvalCritForm=cf;const rngC=_evalRng(200000+cf);evalCritFormNum=(evalCritFormNum%EVAL_FORMAS)+1;_injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});saveProgress();
  document.getElementById('evalcrit-screen-title').textContent=`🧠 Prueba de la promesa · Forma ${cf} · Para quién y qué le cambia · Ruta de la Marca`;
  evalCritAnsVisible=false;
  const out=document.getElementById('evalCritOut');out.innerHTML='';

  const kase=_rotaF(critCaseBank,cf);
  const s1=document.createElement('div');
  s1.innerHTML=`<div class="eval-section-title">I. Simulacro de Presión: la interpelación <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${kase.txt}</div>${critCaseQuestions.map((q,i)=>`<div class="crit-q-block"><div class="crit-q-label">${q}</div><textarea class="crit-textarea" rows="2" aria-label="${q}"></textarea><div class="crit-pauta">${critCaseGuides[i]}</div></div>`).join('')}<div class="crit-selfscore"><label for="critScore0">Obtenido:</label><input type="number" id="critScore0" class="crit-score-input" data-score="0" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s1);

  const err=_rotaF(critErrorBank,cf);
  const s2=document.createElement('div');
  s2.innerHTML=`<div class="eval-section-title">II. Corrige el error <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${err.txt}</div><p style="font-size:0.85rem;margin-bottom:0.5rem;">Identifica <strong>dos errores</strong> y corrígelos con tus propias palabras:</p><div class="crit-q-block"><div class="crit-q-label">Error 1 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 1 y su corrección"></textarea><div class="crit-pauta">${err.g1}</div></div><div class="crit-q-block"><div class="crit-q-label">Error 2 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 2 y su corrección"></textarea><div class="crit-pauta">${err.g2}</div></div><div class="crit-selfscore"><label for="critScore1">Obtenido:</label><input type="number" id="critScore1" class="crit-score-input" data-score="1" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s2);

  const dec=_rotaF(critDecisionBank,cf);
  const s3=document.createElement('div');
  s3.innerHTML=`<div class="eval-section-title">III. Toma de decisiones bajo presión <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${dec}</div><div class="crit-q-block"><div class="crit-q-label">¿Para quién y qué le cambia, qué se pide a cambio y con qué condición por escrito aceptarías? Explica por qué tu salida es mejor que aceptar completo o que rechazar de plano.</div><textarea class="crit-textarea" rows="4" aria-label="Recomendación y justificación"></textarea><div class="crit-pauta">${critDecisionGuide}</div></div><div class="crit-selfscore"><label for="critScore2">Obtenido:</label><input type="number" id="critScore2" class="crit-score-input" data-score="2" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s3);

  const cmp=_rotaF(critCompareBank,cf);
  const s4=document.createElement('div');
  s4.innerHTML=`<div class="eval-section-title">IV. Comparación razonada <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-compare-grid"><div class="crit-compare-box"><h5>Caso A</h5>${cmp.a}</div><div class="crit-compare-box"><h5>Caso B</h5>${cmp.b}</div></div><div class="crit-q-block"><div class="crit-q-label">1. ¿Qué gana cada caso y cuál aguanta un cambio de funcionario? 2. ¿Por qué no son el mismo caso?</div><textarea class="crit-textarea" rows="4" aria-label="Comparación razonada de los casos A y B"></textarea><div class="crit-pauta">Caso A: ${cmp.ga} · Caso B: ${cmp.gb} · ${cmp.gr}</div></div><div class="crit-selfscore"><label for="critScore3">Obtenido:</label><input type="number" id="critScore3" class="crit-score-input" data-score="3" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s4);

  const causes=_pickF(critCauseBank,2,rngC),effects=_pickF(critEffectBank,3,rngC);
  let ceRows='';
  causes.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Causa</span>${it.cause}</div><div class="crit-ce-cell"><span class="crit-ce-tag">Efecto</span><textarea class="crit-textarea" rows="2" aria-label="Efecto de: ${it.cause}" placeholder="Escribe el efecto..."></textarea></div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  effects.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell"><span class="crit-ce-tag">Causa</span><textarea class="crit-textarea" rows="2" aria-label="Causa de: ${it.effect}" placeholder="Escribe la causa..."></textarea></div><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Efecto</span>${it.effect}</div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  const s5=document.createElement('div');
  s5.innerHTML=`<div class="eval-section-title">V. Análisis de causas y efectos <span class="eval-pts">20 pts</span></div><div class="eval-item">${ceRows}<div class="crit-selfscore"><label for="critScore4">Obtenido:</label><input type="number" id="critScore4" class="crit-score-input" data-score="4" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s5);

  window._evalCritData={kase,err,dec,cmp,causes,effects};
  const totalPanel=document.createElement('div');totalPanel.id='evalCritTotalResult';totalPanel.className='crit-total-panel';totalPanel.innerHTML='<strong>🧮 Autoevaluación:</strong> responde cada sección, compara con la <em>Pauta</em> y anota tu puntaje (0–20) en cada casilla. Luego presiona <em>Calcular Total</em>.';out.appendChild(totalPanel);
  fin('s-evaluacion');
}
function toggleEvalCritAns(){evalCritAnsVisible=!evalCritAnsVisible;document.querySelectorAll('#evalCritOut .crit-pauta').forEach(el=>el.style.display=evalCritAnsVisible?'block':'none');sfx('click');}
function calcCritTotal(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  let total=0;
  document.querySelectorAll('#evalCritOut .crit-score-input').forEach(inp=>{let v=parseInt(inp.value)||0;v=Math.max(0,Math.min(20,v));inp.value=v;total+=v;});
  const panel=document.getElementById('evalCritTotalResult');
  if(panel){panel.className='crit-total-panel '+(total>=70?'eval-auto-pass':'eval-auto-risk');panel.innerHTML=`<strong>Puntaje total autoevaluado: ${total}/100</strong><br><em>Compara siempre tus respuestas con la Pauta antes de anotar el puntaje de cada sección.</em>`;}
  const formKey='crit_'+(window._currentEvalCritForm||1);
  if(total>=70){if(!xpTracker.wgt.has(formKey)){xpTracker.wgt.add(formKey);pts(8);}showToast('🎯 Prueba de la promesa: '+total+'/100');}
  else showToast('🧮 Puntaje registrado: '+total+'/100. ¡Sigue practicando!');
}
function printEvalCrit(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  const forma=window._currentEvalCritForm||1;const d=window._evalCritData;
  const lines=(n)=>Array(n).fill('<div class="ln"></div>').join('');
  let s1=`<div class="sec-title"><span>I. Simulacro de Presión: la interpelación</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.kase.txt}</p>`;
  critCaseQuestions.forEach(q=>{s1+=`<p class="crit-print-q">${q}</p>${lines(1)}`;});
  let s2=`<div class="sec-title"><span>II. Corrige el error</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.err.txt}</p><p class="crit-print-q">Identifica dos errores y corrígelos con tus propias palabras:</p><p class="crit-print-q"><strong>Error 1:</strong></p>${lines(1)}<p class="crit-print-q"><strong>Error 2:</strong></p>${lines(1)}`;
  let s3=`<div class="sec-title"><span>III. Toma de decisiones bajo presión</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.dec}</p><p class="crit-print-q">¿Para quién y qué le cambia, qué se pide a cambio y con qué condición por escrito aceptarías? Explica por qué tu salida es mejor que aceptar completo o que rechazar de plano.</p>${lines(2)}`;
  let s4=`<div class="sec-title"><span>IV. Comparación razonada</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><div class="crit-compare-print-grid"><div class="crit-compare-print-box"><strong>Caso A:</strong> ${d.cmp.a}</div><div class="crit-compare-print-box"><strong>Caso B:</strong> ${d.cmp.b}</div></div><p class="crit-print-q">1. ¿Qué gana cada caso y cuál aguanta un cambio de funcionario? 2. ¿Por qué no son el mismo caso?</p>${lines(2)}`;
  let ceTbl='<table class="crit-print-tbl"><tr><th>Causa</th><th>Efecto</th></tr>';
  d.causes.forEach(it=>{ceTbl+=`<tr><td>${it.cause}</td><td></td></tr>`;});
  d.effects.forEach(it=>{ceTbl+=`<tr><td></td><td>${it.effect}</td></tr>`;});
  ceTbl+='</table>';
  let s5=`<div class="sec-title"><span>V. Análisis de causas y efectos</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div>${ceTbl}`;
  let pR='';
  pR+=`<div class="p-sec"><div class="p-ttl">I. Caso</div>${critCaseQuestions.map((q,i)=>`<div class="p-crit-line"><strong>${i+1}.</strong> ${critCaseGuides[i]}</div>`).join('')}</div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">II. Corrige el error</div><div class="p-crit-line"><strong>Error 1:</strong> ${d.err.g1}</div><div class="p-crit-line"><strong>Error 2:</strong> ${d.err.g2}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">III. Toma de decisiones</div><div class="p-crit-line">${critDecisionGuide}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">IV. Comparación</div><div class="p-crit-line"><strong>Caso A:</strong> ${d.cmp.ga}</div><div class="p-crit-line"><strong>Caso B:</strong> ${d.cmp.gb}</div><div class="p-crit-line">${d.cmp.gr}</div></div>`;
  pR+=`<div class="p-sec" style="grid-column:1/-1;"><div class="p-ttl">V. Causas y efectos</div>${d.causes.map(it=>`<div class="p-crit-line"><strong>Causa:</strong> ${it.cause} → <strong>Efecto:</strong> ${it.guide}</div>`).join('')}${d.effects.map(it=>`<div class="p-crit-line"><strong>Efecto:</strong> ${it.effect} → <strong>Causa:</strong> ${it.guide}</div>`).join('')}</div>`;
  const doc=`<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>Prueba de la promesa Para quién y qué le cambia · Ruta de la Marca · Forma ${forma}</title><style>*{margin:0;padding:0;box-sizing:border-box;}body{font-family:Arial,Helvetica,sans-serif;font-size:11pt;color:#111;background:#fff;padding:1mm 5mm;}.ph{margin-bottom:0.3rem;}.ph h2{font-size:11pt;font-weight:700;text-align:center;margin-bottom:0.2rem;}.ph-line{display:flex;align-items:baseline;gap:5px;margin-bottom:3px;}.ph-fill{flex:1;border-bottom:1px solid #555;min-height:12px;display:block;}.ph-m{display:inline-block;min-width:80px;border-bottom:1px solid #555;}.ph-s{display:inline-block;min-width:52px;border-bottom:1px solid #555;}.ph-xs{display:inline-block;min-width:36px;border-bottom:1px solid #555;}.ph-crit{font-size:9.5pt;text-align:center;color:#555;margin-top:0.1rem;}.sec-title{font-size:10.5pt;font-weight:700;padding:0.1rem 0.4rem;margin:0.2rem 0 0.1rem;display:flex;justify-content:space-between;align-items:center;border-left:4px solid #3b3a86;background:#ece9fb;color:#3b3a86;}.obt-row{display:flex;align-items:baseline;gap:4px;font-size:9.5pt;font-weight:700;font-style:italic;color:#3b3a86;}.obt-lbl{white-space:nowrap;}.obt-line{display:inline-block;min-width:50px;border-bottom:1.5px solid #3b3a86;height:12px;}.obt-pct{white-space:nowrap;}.crit-print-scenario{font-size:10.5pt;background:#ece9fb;border-left:3px solid #3b3a86;padding:0.2rem 0.5rem;margin:0.1rem 0 0.2rem;line-height:1.3;}.crit-print-q{font-size:10pt;font-weight:600;margin:0.15rem 0 0.08rem;line-height:1.25;}.ln{border-bottom:1px solid #111;min-height:12px;margin-bottom:2px;}.crit-compare-print-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.5rem;margin:0.15rem 0;}.crit-compare-print-box{font-size:9.5pt;background:#ece9fb;border-radius:4px;padding:0.25rem 0.4rem;line-height:1.25;}.crit-print-tbl{width:100%;border-collapse:collapse;font-size:9.5pt;margin-top:0.15rem;}.crit-print-tbl th,.crit-print-tbl td{border:1px solid #999;padding:0.3rem 0.45rem;text-align:left;height:30px;vertical-align:middle;}.crit-print-tbl th{background:#ece9fb;}.pauta-wrap{page-break-before:always;padding-top:0.4rem;}.p-head{border-bottom:2px solid #333;padding-bottom:0.3rem;margin-bottom:0.4rem;text-align:center;}.p-main{font-size:9.5pt;font-weight:700;}.p-sub{font-size:7pt;color:#c00;font-weight:700;margin:0.08rem 0;}.p-meta{font-size:7pt;color:#555;}.p-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.4rem 0.9rem;}.p-sec{border:1px solid #ccc;border-radius:4px;padding:0.3rem 0.45rem;}.p-ttl{font-size:8pt;font-weight:700;border-bottom:1px solid #ddd;padding-bottom:0.1rem;margin-bottom:0.18rem;}.p-crit-line{font-size:7.5pt;color:#007a00;margin-bottom:0.18rem;line-height:1.35;}.total-row{display:flex;align-items:baseline;justify-content:flex-start;margin-left:20%;gap:7px;font-size:11pt;font-weight:700;font-style:italic;margin-top:0.2rem;padding:0.1rem 0;color:#3b3a86;}.total-row .obt-line{min-width:80px;border-bottom:1.5px solid #3b3a86;}.forma-tag{font-size:7pt;color:#555;border:1px solid #bbb;padding:1px 5px;border-radius:3px;background:white;}.print-foot{position:fixed;bottom:2mm;left:0;right:0;display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:7.5pt;color:#111;background:#fff;padding:1px 3px;}.pf-item{display:inline-flex;align-items:center;gap:4px;}.pf-line{display:inline-block;width:26mm;border-bottom:1px solid #333;}.pf-box{display:inline-block;width:3.4mm;height:3.4mm;border:1px solid #333;}@media print{@page{size:letter portrait;margin:12.7mm;}}</style></head><body><div class="ph"><h2>Evaluación Competencial · Prueba de la promesa · Para quién y qué le cambia · Ruta de la Marca · Etapa 1 · Marketing y Marca</h2><div class="ph-line"><strong>Nombre:</strong><span class="ph-fill">&nbsp;</span><strong>Fecha:</strong><span class="ph-m">&nbsp;</span></div><div class="ph-line"><strong>Institución:</strong><span class="ph-fill">&nbsp;</span><strong>Grado y Sección:</strong><span class="ph-s">&nbsp;</span><strong>Nº Lista:</strong><span class="ph-xs">&nbsp;</span></div><p class="ph-crit">Valor total: 100 puntos · 5 secciones de 20 puntos</p></div>${s1}${s2}${s3}${s4}${s5}<div class="total-row"><span>Total, obtenido</span><span class="obt-line"></span><span>de 100</span></div><div class="pauta-wrap"><div class="p-head"><div class="p-main">✅ PAUTA: Prueba de la promesa · Para quién y qué le cambia · Ruta de la Marca · Forma ${forma}</div><div class="p-sub">Documento exclusivo del docente · No distribuir al estudiante</div><div class="p-meta">Valor total: 100 pts | 5 secciones × 20 pts c/u, respuesta abierta, usar como guía de corrección</div></div><div class="p-grid">${pR}</div></div><div class="print-foot"><span class="pf-item"><strong>Nº de Evaluación temática realizada:</strong><span class="pf-line">&nbsp;</span></span><span class="pf-item"><strong>Evaluación con valor en el parcial</strong><span class="pf-box"></span></span><span class="pf-item"><strong>Evaluación solo de repaso</strong><span class="pf-box"></span></span><span class="forma-tag">Forma ${forma}</span></div></body></html>`;
  const win=window.open('','_blank','');
  if(!win){showToast('⚠️ Activa las ventanas emergentes para imprimir');return;}
  win.document.write(doc);win.document.close();setTimeout(()=>win.print(),400);
}

