const timelineData=[{"y":"1","icon":"🎯","label":"La audiencia","text":"Para quién es esto <strong>exactamente</strong>. <strong>Resuelve:</strong> a quién se le habla y con qué palabras. <strong>Se rompe:</strong> cuando se dice «para todo el mundo», que no es nadie. <strong>En M.E.T.A.S:</strong> la maestra de sexto a las nueve de la noche."},{"y":"2","icon":"😣","label":"El dolor","text":"Lo que le duele hoy, dicho <strong>con sus palabras</strong>. <strong>Resuelve:</strong> que la persona se reconozca en la primera línea. <strong>Se rompe:</strong> cuando se describe con las palabras de uno. <strong>En M.E.T.A.S:</strong> «mañana toca fracciones y no tengo nada preparado»."},{"y":"3","icon":"🔨","label":"El trabajo por hacer","text":"Para qué te <strong>contrata</strong> de verdad. <strong>Resuelve:</strong> distinguir lo que pide de lo que necesita. <strong>Se rompe:</strong> cuando se cree que quiere el producto. <strong>En M.E.T.A.S:</strong> no quiere una aplicación, quiere terminar de calificar."},{"y":"4","icon":"📣","label":"La promesa","text":"Qué le cambia, en <strong>una frase corta y verificable</strong>. <strong>Resuelve:</strong> que alguien pueda repetirla sin uno delante. <strong>Se rompe:</strong> cuando lleva adjetivos en vez de resultado. <strong>En M.E.T.A.S:</strong> «mañana tienes la clase lista»."},{"y":"5","icon":"📄","label":"La prueba","text":"Algo que se puede <strong>tocar hoy</strong>. <strong>Resuelve:</strong> que no haya que creer en la palabra de nadie. <strong>Se rompe:</strong> con cifras que nadie puede verificar. <strong>En M.E.T.A.S:</strong> la ficha impresa, el Campeonísimo y el teléfono sin señal."},{"y":"6","icon":"✨","label":"La diferencia","text":"Por qué esto y <strong>no lo que ya existe</strong>. <strong>Resuelve:</strong> la comparación que el otro va a hacer igual. <strong>Se rompe:</strong> al querer ser mejor en todo. <strong>En M.E.T.A.S:</strong> funciona sin internet y se imprime en blanco y negro."},{"y":"7","icon":"🏷️","label":"El nombre y el logo","text":"La <strong>etiqueta</strong> de todo lo anterior. <strong>Resuelve:</strong> que se pueda señalar y recordar. <strong>Se rompe:</strong> cuando se hace primero. <strong>En M.E.T.A.S:</strong> va al final, y en el idioma de quien lo va a usar."}];
function initTimeline(){const track=document.getElementById('timelineTrack');if(!track)return;timelineData.forEach((d,i)=>{const b=document.createElement('button');b.className='tl-node';b.type='button';b.dataset.idx=i;b.innerHTML=`<span class="tl-dot">${d.icon}</span><span class="tl-year">${d.y}</span><span class="tl-label">${d.label}</span>`;b.onclick=()=>showTimeline(i);track.appendChild(b);});}
function showTimeline(i){const d=timelineData[i];document.querySelectorAll('.tl-node').forEach(n=>n.classList.remove('tl-active'));document.querySelector(`.tl-node[data-idx="${i}"]`).classList.add('tl-active');document.getElementById('tlInfoIcon').textContent=d.icon;document.getElementById('tlInfoText').innerHTML=`<strong>${d.y} · ${d.label}.</strong> ${d.text}`;document.getElementById('tlInfo').style.display='flex';sfx('click');}

